# flange: generated by ShapeBridge (https://github.com/gazi-faysal-jubayer/shapebridge)
# Units: mm. Edit the parameters below; geometry updates from them.

import math
import cadquery as cq

# sketch planes: (x direction, normal); the normal is x × y
FRAMES = {"XY": ((1, 0, 0), (0, 0, 1)), "XZ": ((1, 0, 0), (0, -1, 0)), "YZ": ((0, 1, 0), (1, 0, 0))}


def plane(base, offset):
    x, n = FRAMES[base]
    return cq.Workplane(cq.Plane(origin=tuple(c * offset for c in n), xDir=x, normal=n))


def build(outer_d=120, bore_d=40, plate=12, hub_d=60, hub_h=20, bolt_circle=45, bolts=6):
    # disc
    def tool_disc():
        return plane("XY", 0).moveTo(0, 0).circle(outer_d / 2).extrude(plate)
    result = tool_disc()
    # hub
    def tool_hub():
        return plane("XY", plate).moveTo(0, 0).circle(hub_d / 2).extrude(hub_h)
    result = result.union(tool_hub())
    # bore
    def tool_bore():
        solids = []
        top = cq.Vector(0, 0, plate + hub_h) + cq.Vector((0, 0, 1)) * 0.0001
        solids.append(cq.Solid.makeCylinder(bore_d / 2, plate + hub_h + 0.0001, top, cq.Vector((0, 0, -1))))
        return cq.Workplane().add(cq.Compound.makeCompound(solids))
    result = result.cut(tool_bore())
    # bolt
    def tool_bolt():
        solids = []
        top = cq.Vector(bolt_circle, 0, plate) + cq.Vector((0, 0, 1)) * 0.0001
        solids.append(cq.Solid.makeCylinder(9 / 2, plate + 0.0001, top, cq.Vector((0, 0, -1))))
        return cq.Workplane().add(cq.Compound.makeCompound(solids))
    result = result.cut(tool_bolt())
    # bolt_ring
    for i in range(1, int(bolts)):
        result = result.cut(tool_bolt().rotate((0, 0, 0), (0, 0, 1), 360 * i / bolts))
    # edge
    result = result.faces(">Z").edges().chamfer(1)
    return result


result = build()
if "show_object" in globals():
    show_object(result)
elif __name__ == "__main__":
    cq.exporters.export(result, "flange.step")
